<style>
:root{--xd7-navy:#071b3b;--xd7-blue:#1d79f2;--xd7-mint:#21c58b;--xd7-lime:#d8f36a;--xd7-sky:#edf8ff;--xd7-ink:#10213d;--xd7-muted:#64748b;--gold:var(--xd7-mint);--ink:var(--xd7-ink);--muted:var(--xd7-muted);--wide:min(1240px,calc(100% - 56px))}
html{scroll-behavior:smooth}body{background:#fff;color:var(--xd7-ink);font-family:"Segoe UI",Arial,sans-serif}.xd5-page{overflow:hidden}
.xd5-header{position:relative;background:#fff;color:var(--xd7-ink);box-shadow:0 8px 40px rgba(24,73,120,.08)}.xd5-utility{background:var(--xd7-navy);color:#d7e6fa;border:0}.xd5-nav-wrap{min-height:92px}.xd5-brand{font-size:0}.xd5-brand:after{content:"KLEAN";font-size:28px;font-weight:900;letter-spacing:-.05em;color:var(--xd7-navy)}.xd5-brand:before{display:grid;width:38px;height:38px;place-items:center;border-radius:50% 50% 50% 12%;background:var(--xd7-mint);color:#fff;content:"✦";font-size:19px}.xd5-brand:has(img):before,.xd5-brand:has(img):after{display:none}.xd5-brand img{max-width:170px}.xd5-nav-wrap nav{gap:28px;font-size:13px;color:var(--xd7-navy);letter-spacing:.04em}.xd5-nav-wrap nav a:hover{color:var(--xd7-blue)}.xd5-hotline{padding:13px 20px;border-radius:999px;background:var(--xd7-lime);color:var(--xd7-navy);font-size:15px}
.xd5-hero{min-height:700px;background:var(--xd7-sky);color:var(--xd7-navy)}.xd5-hero__slide{width:100%}.xd5-hero__slide:after{position:absolute;inset:0;background:linear-gradient(90deg,var(--xd7-sky) 0 43%,transparent 68%);content:"";pointer-events:none}.xd5-hero img{position:absolute;right:0;width:62%;filter:saturate(.88);clip-path:ellipse(76% 72% at 76% 48%)}.xd5-veil{display:none}.xd5-hero-copy{z-index:2;min-height:700px}.xd5-hero-copy>div{max-width:570px;margin:0}.xd5-kicker,.xd5-eyebrow{color:var(--xd7-mint);font-size:13px;font-weight:850;letter-spacing:.14em;text-transform:uppercase}.xd5-hero h1{margin:18px 0;font-size:clamp(45px,5vw,74px);font-weight:850;letter-spacing:-.055em;line-height:.98}.xd5-hero p{max-width:520px;color:var(--xd7-muted);font-size:18px}.xd5-btn{min-height:56px;align-items:center;padding:0 28px;border-radius:999px;background:var(--xd7-blue);color:#fff;box-shadow:0 15px 35px rgba(29,121,242,.25);transition:.25s}.xd5-btn:hover{background:var(--xd7-navy);transform:translateY(-3px)}
.xd5-section{position:relative;padding:105px 0;background:#fff}.xd5-section:nth-of-type(odd){background:var(--xd7-sky)}.xd5-title{max-width:800px;margin:12px 0 0;font-size:clamp(36px,4vw,58px);font-weight:850;letter-spacing:-.045em;line-height:1.06}
.xd5-services{grid-template-columns:repeat(4,1fr);gap:22px;margin-top:52px}.xd5-service{min-height:390px;padding:28px;border:0;border-radius:24px;background:#fff;box-shadow:0 18px 55px rgba(18,65,105,.1);transition:.28s}.xd5-service:before{display:grid;width:54px;height:54px;place-items:center;margin-bottom:10px;border-radius:18px;background:#e7fff6;color:var(--xd7-mint);content:"✦";font-size:24px}.xd5-service h3{font-size:21px;line-height:1.3}.xd5-service p{color:var(--xd7-muted)}.xd5-service img{height:150px;border-radius:16px}.xd5-service:hover{transform:translateY(-12px);box-shadow:0 26px 70px rgba(18,65,105,.16)}.xd5-service:nth-child(even):before{background:#eef5ff;color:var(--xd7-blue)}
.xd5-about{grid-template-columns:.95fr 1.05fr;gap:90px}.xd5-about-media{min-height:500px}.xd5-about-media:after{position:absolute;right:6%;bottom:-18px;width:150px;height:150px;border:24px solid var(--xd7-lime);border-radius:50%;content:"";opacity:.65}.xd5-about-media img{width:88%;height:470px;border-radius:42% 18px 42% 18px}.xd5-about-badge{right:0;bottom:22px;width:42%;padding:30px;border-radius:24px;background:var(--xd7-navy);box-shadow:0 15px 35px rgba(7,27,59,.22)}.xd5-progress{height:10px;border-radius:99px;background:#dfeaf4;overflow:hidden}.xd5-progress i{border-radius:inherit;background:linear-gradient(90deg,var(--xd7-mint),var(--xd7-blue))}
.xd5-benefits{background:var(--xd7-navy)!important;color:#fff}.xd5-benefit-grid{gap:80px}.xd5-benefit-grid>div:first-child{order:2}.xd5-benefit-grid img{height:570px;border-radius:36px}.xd5-benefit-list b:before{border-radius:16px;background:var(--xd7-lime);color:var(--xd7-navy);content:"✓"}
.xd5-testimonial{background:#fff!important}.xd5-testimonial-grid{grid-template-columns:1.1fr repeat(3,1fr);gap:18px}.xd5-quote{border:1px solid #e3edf5;border-radius:24px;box-shadow:none}.xd5-quote:before{display:block;margin-bottom:20px;color:var(--xd7-mint);content:"“";font-size:58px;font-weight:900;line-height:.5}.xd5-team article{border-radius:28px;background:#fff;color:var(--xd7-ink);box-shadow:0 18px 55px rgba(18,65,105,.11)}.xd5-team img{height:380px}.xd5-team article:nth-child(2){transform:translateY(28px)}
.xd5-contact{background:linear-gradient(135deg,var(--xd7-blue),var(--xd7-navy))!important}.xd5-contact-card{border-radius:30px;box-shadow:0 30px 70px rgba(0,0,0,.2)}.xd5-contact-card input,.xd5-contact-card textarea{border-radius:14px;background:#f1f7fc}.xd5-post{overflow:hidden;border-radius:24px;background:#fff;box-shadow:0 18px 50px rgba(18,65,105,.1)}.xd5-post img{height:245px}.xd5-post div{padding:26px}.xd5-partners{background:#f5fbff}.xd5-partner{border-radius:16px;background:#fff}
.xd5-footer{padding:70px 0;background:var(--xd7-navy);color:#fff}.xd5-footer-top{border-color:rgba(255,255,255,.12)}.xd5-footer-top small{color:var(--xd7-mint)}.xd5-footer-grid{gap:60px}.xd5-footer input{border-radius:999px 0 0 999px}.xd5-footer button{border-radius:0 999px 999px 0;background:var(--xd7-mint);color:var(--xd7-navy)}
[data-xd-reveal]{opacity:0;transform:translateY(42px);transition:opacity .72s ease,transform .72s cubic-bezier(.2,.8,.2,1);transition-delay:var(--reveal-delay,0ms)}[data-xd-reveal].is-visible{opacity:1;transform:none}
@media(max-width:900px){.xd5-services{grid-template-columns:1fr 1fr}.xd5-testimonial-grid{grid-template-columns:1fr 1fr}.xd5-team article:nth-child(2){transform:none}}
@media(max-width:620px){:root{--wide:min(100% - 30px,1240px)}.xd5-header{background:#fff}.xd5-nav-wrap>button{border-color:#c9d8e7;color:var(--xd7-navy);border-radius:999px}.xd5-nav-wrap nav{color:var(--xd7-navy)}.xd5-hero__slide:after{background:linear-gradient(90deg,rgba(237,248,255,.97),rgba(237,248,255,.74))}.xd5-hero img{width:100%;clip-path:none}.xd5-hero-copy{position:relative}.xd5-hero h1{font-size:45px}.xd5-services,.xd5-testimonial-grid{grid-template-columns:1fr}.xd5-section{padding:72px 0}.xd5-about-media img{width:100%;height:410px}.xd5-benefit-grid>div:first-child{order:0}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}[data-xd-reveal]{opacity:1;transform:none;transition:none}}
</style>
